 const queue={get busy(){return running;},get replaying(){return replaying;},enqueue(action){return new Promise((resolve,reject)=>{jobs.push({action,resolve,reject});void drain();});},watch(value,label){const promise=Promise.resolve(value);watched.add(promise);labels.set(promise,label);report();promise.finally(()=>{watched.delete(promise);labels.delete(promise);report();}).catch(()=>{});return promise;},dispatch(action){replaying=true;try{return action();}finally{replaying=false;}},run(action){return replaying?queue.watch(action(),'action'):queue.enqueue(action);}};return queue;
