function owner(doc){let win=doc.defaultView;try{while(win.parent!==win&&win.parent.document)win=win.parent;}catch{}return win;}
const OWNED='.phone16-root,.dn-window,.sb-window,.routine-scene,.collection-window,.fw-host,.scene-phone-cluster,.floating-surface,.location-window,.dd-window,.cs-window,.np-window,.rg-window';
function animating(state){for(const scope of state.scopes){if(scope.host&&!scope.host.isConnected){state.scopes.delete(scope);continue;}const marker=scope.querySelector('[data-turn-progress],[data-book-changing],[data-scene-moving]');if(marker){if(state.win.__ST_LOCAL_PREVIEW__||state.win.location?.search?.includes('motionAudit=1'))state.win.document.documentElement.dataset.motionWait=JSON.stringify({class:marker.className,dataset:{...marker.dataset}});return true;}}for(const doc of state.docs){if(doc.defaultView!==state.win&&doc.defaultView?.frameElement&&!doc.defaultView.frameElement.isConnected){state.docs.delete(doc);continue;}if(doc.querySelector('[data-turn-progress],[data-book-changing],[data-scene-moving]'))return true;for(const animation of doc.getAnimations?.()??[]){if(['running','pending'].includes(animation.playState)&&animation.effect?.getTiming?.().iterations!==Infinity&&animation.effect?.target?.closest?.(OWNED)){if(state.win.__ST_LOCAL_PREVIEW__||state.win.location?.search?.includes('motionAudit=1'))state.win.document.documentElement.dataset.motionWait=JSON.stringify({class:animation.effect.target.className,name:animation.animationName,state:animation.playState,timing:animation.effect.getTiming()});return true;}}}return false;}
